cd /tmp && python3 -c "
import json,re
d=json.load(open('hig_layout.json'))
def walk(o,out):
    if isinstance(o,dict):
        t=o.get('type')
        if t=='text': out.append(o.get('text',''))
        if t=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        if t=='heading': out.append('\n\n## '+o.get('text','')+'\n')
        if t=='table':
            out.append('\n[TABLE]\n')
            for row in o.get('rows',[]):
                cells=[]
                for c in row:
                    b=[]; walk(c,b); cells.append(''.join(b).strip())
                out.append(' | '.join(cells)+'\n')
            out.append('[/TABLE]\n')
            return
        if t=='paragraph':
            for c in o.get('inlineContent',[]): walk(c,out)
            out.append('\n')
            return
        for k,v in o.items():
            if k in ('rows',): continue
            walk(v,out)
    elif isinstance(o,list):
        for i in o: walk(i,out)
out=[]
walk(d,out)
txt=''.join(out)
open('hig_layout.txt','w').write(txt)
print(len(txt))
"
